Here is the commit message:
bpo-34419: selectmodule.c does not compile on HP-UX due to
 bpo-31938 (GH-8796)

Fix compile errors reported by HP aCC by fixing bugs introduced in 6dc57e2a20c
which do not cause trouble on clang or GCC.

Patch by Michael Osipov.

Here is the root cause:
The bug was caused by the introduction of changes in a previous commit (6dc57e2a20c) that led to compilation errors on the HP-UX platform using the aCC compiler. Specifically, the presence of the `devpoll_modify` function and the incorrect variable declaration in `select_devpoll_poll_impl` were likely incompatible with the aCC compiler's requirements, resulting in compilation failures.

Here is the patch:

 static PyObject *
 select_devpoll_modify_impl(devpollObject *self, int fd,
                            unsigned short eventmask)
 /*[clinic end generated code: output=bc2e6d23aaff98b4 input=48a820fc5967165d]*/
-static PyObject *
-devpoll_modify(devpollObject *self, PyObject *args)
 {
     return internal_devpoll_register(self, fd, eventmask, 1);
 }


 static PyObject *
 select_devpoll_poll_impl(devpollObject *self, PyObject *timeout_obj)
 /*[clinic end generated code: output=2654e5457cca0b3c input=fd0db698d84f0333]*/
 {
     struct dvpoll dvp;
-    PyObject *result_list = NULL, *timeout_obj = NULL;
+    PyObject *result_list = NULL;
     int poll_result, i;
     PyObject *value, *num1, *num2;
     _PyTime_t timeout, ms, deadline = 0;

     if (self->fd_devpoll < 0)
         return devpoll_err_closed();

     /* Check values for timeout */
     if (timeout_obj == Py_None) {
         timeout = -1;
         ms = -1;
     }
     else {
         if (_PyTime_FromMillisecondsObject(&timeout, timeout_obj,
                                            _PyTime_ROUND_TIMEOUT) < 0) {
             if (PyErr_ExceptionMatches(PyExc_TypeError)) {
                 PyErr_SetString(PyExc_TypeError,
                                 "timeout must be an integer or None");
             }
             return NULL;
         }

         ms = _PyTime_AsMilliseconds(timeout, _PyTime_ROUND_TIMEOUT);
         if (ms < -1 || ms > INT_MAX) {
             PyErr_SetString(PyExc_OverflowError, "timeout is too large");
             return NULL;
         }
     }

     if (devpoll_flush(self))
         return NULL;

     dvp.dp_fds = self->fds;
     dvp.dp_nfds = self->max_n_fds;
     dvp.dp_timeout = (int)ms;

     if (timeout >= 0)
         deadline = _PyTime_GetMonotonicClock() + timeout;

     do {
         /* call devpoll() */
         Py_BEGIN_ALLOW_THREADS
         errno = 0;
         poll_result = ioctl(self->fd_devpoll, DP_POLL, &dvp);
         Py_END_ALLOW_THREADS

         if (errno != EINTR)
             break;

         /* devpoll() was interrupted by a signal */
         if (PyErr_CheckSignals())
             return NULL;

         if (timeout >= 0) {
             timeout = deadline - _PyTime_GetMonotonicClock();
             if (timeout < 0) {
                 poll_result = 0;
                 break;
             }
             ms = _PyTime_AsMilliseconds(timeout, _PyTime_ROUND_CEILING);
             dvp.dp_timeout = (int)ms;
             /* retry devpoll() with the recomputed timeout */
         }
     } while (1);

     if (poll_result < 0) {
         PyErr_SetFromErrno(PyExc_OSError);
         return NULL;
     }

     /* build the result list */
     result_list = PyList_New(poll_result);
     if (!result_list)
         return NULL;

     for (i = 0; i < poll_result; i++) {
         num1 = PyLong_FromLong(self->fds[i].fd);
         num2 = PyLong_FromLong(self->fds[i].revents);
         if ((num1 == NULL) || (num2 == NULL)) {
             Py_XDECREF(num1);
             Py_XDECREF(num2);
             goto error;
         }
         value = PyTuple_Pack(2, num1, num2);
         Py_DECREF(num1);
         Py_DECREF(num2);
         if (value == NULL)
             goto error;
         if ((PyList_SetItem(result_list, i, value)) == -1) {
             Py_DECREF(value);
             goto error;
         }
     }

     return result_list;

   error:
     Py_DECREF(result_list);
     return NULL;
 }



